create function pg_temp.correction_data(p_id text default 'c0000000-0000-4000-8000-000000000001') returns jsonb language sql as $$
 select jsonb_build_object('id',p_id,'lot_id',(select d.lot_id from public.sowing_stages s join public.lot_subdivisions d on d.id=s.subdivision_id where s.id='80000000-0000-4000-8000-000000000005'),'expected_version',0,'name','Malla corregida','area_ha',4,'stage_id','80000000-0000-4000-8000-000000000005','planned_sowing_date','2026-01-04','actual_sowing_date','2026-01-05','reason','Corrección ficticia de captura') $$;
create temp table targets_before as select * from public.application_targets;
create temp table stages_before as select * from public.sowing_stages;
create temp table orders_before as select * from public.application_orders;
create temp table products_before as select * from public.application_order_products;
create temp table actual_before as select * from public.application_actual_products;
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||'{"actual_sowing_date":"2026-01-08"}')$q$,'posterior.*aplicación','fecha posterior a receta existente rechazada');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||'{"actual_sowing_date":"2026-01-04"}')$q$,'cierre','fecha anterior a etapa previa rechazada');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||'{"area_ha":4.00001}')$q$,'decimales','superficie no se redondea silenciosamente');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||'{"area_ha":0}')$q$,'positiva','superficie cero rechazada');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||'{"area_ha":"4"}')$q$,'numérica','superficie textual rechazada');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||'{"reason":" "}')$q$,'motivo','motivo obligatorio');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||jsonb_build_object('name',U&'\3000\00A0'))$q$,'Nombre','nombre solo con espacios Unicode rechazado');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||jsonb_build_object('reason',U&'\FEFF\202F'))$q$,'motivo','motivo solo con espacios Unicode rechazado');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||'{"stage_id":"80000000-0000-4000-8000-000000000002"}')$q$,'vigente','etapa ajena no puede corregirse');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||'{"field_id":"30000000-0000-4000-8000-000000000002"}')$q$,'no editables','no se cambia campo por esta RPC');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()-array['stage_id','planned_sowing_date','actual_sowing_date'])$q$,'vigente','superficie requiere siembra vigente');
select pg_temp.assert_true((select count(*)=0 from public.lot_corrections),'errores previos no agregan historial');
select public.correct_project_lot(pg_temp.correction_data());
select pg_temp.assert_true((select name='Malla corregida' and area_ha=4 and correction_version=1 from public.project_lots where id=(pg_temp.correction_data()->>'lot_id')::uuid),'nombre y superficie corregidos en la malla');
select pg_temp.assert_true((select area_ha=4 from public.lot_subdivisions where lot_id=(pg_temp.correction_data()->>'lot_id')::uuid),'subdivisión única conserva identidad y recibe superficie');
select pg_temp.assert_true((select area_ha=4 and actual_sowing_date='2026-01-05' and planned_sowing_date='2026-01-04' and status='planted' from public.sowing_stages where id='80000000-0000-4000-8000-000000000005'),'superficie y ambas fechas vigentes corregidas sin reiniciar siembra');
select pg_temp.assert_true((select to_jsonb(s)=to_jsonb(b) from public.sowing_stages s join stages_before b using(id) where s.id='80000000-0000-4000-8000-000000000001'),'etapa cerrada conserva todos sus datos');
select pg_temp.assert_true((select count(*)=4 and bool_and(area_ha=4) and count(distinct status)=3 from public.application_targets where stage_id in('80000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000005')),'todas las recetas de malla, incluso terminales, reciben superficie');
select pg_temp.assert_true((select bool_and((to_jsonb(t)-array['area_ha','area_correction_id'])=(to_jsonb(b)-array['area_ha','area_correction_id'])) from public.application_targets t join targets_before b using(id)),'estados números fechas nombres y demás datos de destinos intactos');
select pg_temp.assert_true((select bool_and(to_jsonb(t)=to_jsonb(b)) from public.application_targets t join targets_before b using(id) where t.stage_id='80000000-0000-4000-8000-000000000002'),'otra malla de misma orden no cambia');
select pg_temp.assert_true((select jsonb_agg(to_jsonb(o) order by id) from public.application_orders o)=(select jsonb_agg(to_jsonb(o) order by id) from orders_before o),'folios e indicaciones originales intactos');
select pg_temp.assert_true((select jsonb_agg(to_jsonb(p) order by order_id,product_id) from public.application_order_products p)=(select jsonb_agg(to_jsonb(p) order by order_id,product_id) from products_before p),'productos y dosis indicados intactos');
select pg_temp.assert_true((select jsonb_agg(to_jsonb(p) order by target_id,product_id) from public.application_actual_products p)=(select jsonb_agg(to_jsonb(p) order by target_id,product_id) from actual_before p),'mezclas realmente aplicadas intactas');
select pg_temp.assert_true((select "before"->'lot'->>'name'='Lote 1' and ("before"->'lot'->>'area_ha')::numeric=5 and jsonb_array_length("before"->'targets')=4 and ("after"->'lot'->>'area_ha')::numeric=4 and changed_by=auth.uid() and reason<>'' from public.lot_corrections),'originales y corrección con autor/motivo conservados');
select pg_temp.assert_true(public.correct_project_lot(pg_temp.correction_data())='c0000000-0000-4000-8000-000000000001'::uuid,'reintento idéntico no agrega versiones');
select pg_temp.assert_true((select count(*)=1 from public.lot_corrections),'un solo evento tras reintento');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data()||'{"name":"Otro"}')$q$,'identificador','UUID no se reutiliza con otra entrada');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data('c0000000-0000-4000-8000-000000000002'))$q$,'cambió','versión esperada evita sobrescritura');
select pg_temp.expect_error($q$update public.lot_corrections set reason='Atajo'$q$,'permission denied','historial sin UPDATE de cliente');
select pg_temp.expect_error($q$delete from public.lot_corrections$q$,'permission denied','historial sin DELETE de cliente');
select pg_temp.expect_error($q$select request_signature from public.lot_corrections$q$,'permission denied','firma privada no se expone');
select pg_temp.expect_error($q$select write_set from public.lot_corrections$q$,'permission denied','capacidad privada no se expone');
select set_config('rcfito.lot_correction','c0000000-0000-4000-8000-000000000001',true);
select pg_temp.expect_error($q$update public.project_lots set area_ha=3 where name='Malla corregida'$q$,'histórica','GUC de cliente no habilita cambiar superficie');
select pg_temp.expect_error($q$update public.project_lots set correction_version=99 where name='Malla corregida'$q$,'versión','versión no se cambia directamente');
select pg_temp.expect_error($q$update public.application_targets set area_ha=3$q$,'permission denied','destinos no se alteran directamente');
select set_config('rcfito.lot_correction','',true);
select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000005')||'{"indicated_date":"2026-01-07","scheduled_date":"2026-01-08"}',array['80000000-0000-4000-8000-000000000005']::uuid[],pg_temp.mixture());
select pg_temp.assert_true((select area_ha=4 from public.application_targets where order_id='90000000-0000-4000-8000-000000000005'),'las recetas nuevas usan superficie corregida');
select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000004')||'{"indicated_date":"2026-01-07","scheduled_date":"2026-01-08"}',array['80000000-0000-4000-8000-000000000005']::uuid[],pg_temp.mixture());
select pg_temp.assert_true((select area_ha=4 from public.application_targets where order_id='90000000-0000-4000-8000-000000000004'),'reintentar indicación anterior no deshace superficie');
reset role;
create function pg_temp.fail_lot_correction() returns trigger language plpgsql as $$ begin if new.area_ha=3 then raise exception 'Fallo ficticio posterior'; end if; return new; end $$;
create trigger zz_fictitious_failure before update on public.application_targets for each row execute function pg_temp.fail_lot_correction();
set local role authenticated;
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data('c0000000-0000-4000-8000-000000000003')||'{"expected_version":1,"area_ha":3}')$q$,'Fallo ficticio','error posterior revierte corrección completa');
select pg_temp.assert_true((select area_ha=4 and correction_version=1 from public.project_lots where name='Malla corregida') and (select count(*)=1 from public.lot_corrections),'rollback conserva malla y auditoría');
select pg_temp.assert_true((select bool_and(area_ha=4) from public.application_targets where stage_id='80000000-0000-4000-8000-000000000005'),'rollback conserva todas las superficies de recetas');
reset role;
drop trigger zz_fictitious_failure on public.application_targets;
set local role authenticated;
select public.save_sowing_stage(jsonb_build_object('id','80000000-0000-4000-8000-000000000006','subdivision_id',(select subdivision_id from public.sowing_stages where id='80000000-0000-4000-8000-000000000005'),'crop_id','40000000-0000-4000-8000-000000000001','variety_id','50000000-0000-4000-8000-000000000001','area_ha',4,'planned_sowing_date','2026-02-01'));
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data('c0000000-0000-4000-8000-000000000004')||'{"expected_version":1,"area_ha":3}')$q$,'planeada excede','no se recorta una planeación siguiente silenciosamente');
-- A different agricultural unit's audit remains outside the reader's scope.
select public.correct_project_lot(jsonb_build_object('id','c0000000-0000-4000-8000-000000000005','lot_id',(select lot_id from public.lot_subdivisions where id=(select subdivision_id from public.sowing_stages where id='80000000-0000-4000-8000-000000000004')),'expected_version',0,'name','Otra agrícola corregida','reason','Nombre ficticio'));
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select count(*)=1 from public.lot_corrections),'lector solo consulta historial de su agrícola');
select pg_temp.expect_error($q$select public.correct_project_lot(pg_temp.correction_data())$q$,'administrador','lector no corrige');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000003';
select pg_temp.assert_true((select count(*)=0 from public.lot_corrections),'lector sin asignación no consulta correcciones');
reset role;
set local role anon;
select pg_temp.expect_error($q$select public.correct_project_lot('{}')$q$,'permission denied','anónimo no llama RPC');
select pg_temp.expect_error($q$select id from public.lot_corrections$q$,'permission denied','anónimo no consulta historial');
reset role;
rollback;
